INSERT INTO workforce_controls(control_type,title,description,risk_level,approval_route,evidence_required) SELECT 'Appointment','Executive appointment control','Critical executive appointments must be supported by the constitution, approved authority route, appointment instrument and conflict-of-interest checks.','Critical','Board / shareholders where constitution or law requires','Resolution, appointment letter/agreement, identity verification and conflict declaration' WHERE NOT EXISTS (SELECT 1 FROM workforce_controls WHERE title='Executive appointment control');
INSERT INTO workforce_controls(control_type,title,description,risk_level,approval_route,evidence_required) SELECT 'Access','Joiner / mover / leaver control','Access to corporate systems, assets, information and delegated authority must be granted, changed and revoked against verified employment status and authority.','Critical','People Operations + Security + relevant executive','Employment record, access approval, revocation record and audit trail' WHERE NOT EXISTS (SELECT 1 FROM workforce_controls WHERE title='Joiner / mover / leaver control');
INSERT INTO workforce_controls(control_type,title,description,risk_level,approval_route,evidence_required) SELECT 'Equity','Employee equity eligibility control','Employee equity eligibility must reference the approved equity plan, role eligibility, vesting terms and applicable legal/tax review; no dashboard record constitutes a grant.','High','Board / shareholders as applicable + legal/tax review','Approved plan, grant instrument, resolutions and statutory records where required' WHERE NOT EXISTS (SELECT 1 FROM workforce_controls WHERE title='Employee equity eligibility control');
INSERT INTO workforce_controls(control_type,title,description,risk_level,approval_route,evidence_required) SELECT 'Succession','Critical role succession control','Critical roles require identified succession coverage and continuity planning, especially for executive, governance, compliance and control functions.','High','Board / CEO / relevant committee','Succession profile, readiness assessment and continuity plan' WHERE NOT EXISTS (SELECT 1 FROM workforce_controls WHERE title='Critical role succession control');