CREATE TABLE IF NOT EXISTS workforce_positions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, department text NOT NULL, position_title text NOT NULL, job_grade text, position_type text NOT NULL DEFAULT 'Permanent', executive_level text NOT NULL DEFAULT 'Non-Executive', reports_to_position text, appointment_authority text, delegated_authority text, equity_eligible boolean NOT NULL DEFAULT false, succession_criticality text NOT NULL DEFAULT 'Standard', status text NOT NULL DEFAULT 'Planned', jurisdiction text DEFAULT 'Nigeria', description text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workforce_people (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, full_name text NOT NULL, position_id uuid REFERENCES workforce_positions(id), employment_status text NOT NULL DEFAULT 'Planned', engagement_type text NOT NULL DEFAULT 'To Be Determined', start_date date, end_date date, manager_name text, work_location text, equity_eligibility text NOT NULL DEFAULT 'Not Assessed', authority_status text NOT NULL DEFAULT 'Not Assigned', document_status text NOT NULL DEFAULT 'Not Complete', verification_status text NOT NULL DEFAULT 'Unverified', notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workforce_controls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), control_type text NOT NULL, title text NOT NULL, description text NOT NULL, risk_level text NOT NULL DEFAULT 'High', approval_route text, evidence_required text, status text NOT NULL DEFAULT 'Active', created_at timestamptz NOT NULL DEFAULT now());
